import notificationHelper from '@helpers/notificationHelper';
import PohImageUploader, { IPohImageUploaderProps } from '@ui-kit/ImageUploader';
import { showModal } from '@ui-kit/Modal';

const defaultsOpts = {
  fileFormats: ['image/bmp', 'image/gif', 'image/jpg', 'image/jpeg', 'image/png'],
  maxWidth: 9999,
  maxHeight: 9999,
  size: 1024000 * 7, // bytes,
  onFileError(msg: string) {
    notificationHelper.error(msg);
  },
  // mime: 'image/png', //image/jpeg
  quality: 100,
  help: 'Кликните для выбора или перетащите сюда изображение',
};

export const changeAvatarInModal = function (
  param: Omit<IPohImageUploaderProps, 'onChange'> & { title?: string },
  callback: IPohImageUploaderProps['onChange'],
) {
  const defaults = { ...defaultsOpts, ...param };

  showModal({
    title: defaults.title || 'Изменение изображения',
    children: (clos) => (
      <PohImageUploader
        src={defaults.src}
        onChange={(src, saveres) => {
          callback(src, saveres);
          clos();
        }}
        alt={defaults.help}
        editorTitle={defaults?.title}
        validation={{
          size: defaults.size,
          fileFormats: defaults.fileFormats,
          maxHeight: defaults.maxHeight,
          maxWidth: defaults.maxWidth,
        }}
        folder={defaults?.folder}
        width={defaults.width}
        height={defaults.height}
        name={defaults?.name}
        sizes={defaults?.sizes}
      />
    ),
  });
};
